import { test, expect } from '@playwright/test';

test.describe('Dynamic Loading Test', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/dynamic_loading/1');
  });

  test('should reveal hidden content after loading', async ({ page }) => {
    const startButton = page.getByRole('button', { name: 'Start' });
    await expect(page.getByText('Hello World!')).toBeHidden();
    await startButton.click();
    await expect(page.getByText('Loading...')).toBeVisible();
    await expect(page.getByText('Loading...')).toBeHidden({ timeout: 10000 });
    await expect(page.getByText('Hello World!')).toBeVisible();
  });

  test('should show loading indicator during async wait', async ({ page }) => {
    const startButton = page.getByRole('button', { name: 'Start' });
    await startButton.click();
    await expect(page.getByText('Loading...')).toBeVisible();
    await page.waitForTimeout(1000); // Wait for a second to ensure loading is visible
    await expect(page.getByText('Loading...')).toBeVisible();
  });
});
